TOOLS = {
    "bok": "Bokning av tid direkt på sidan är den viktigaste funktionen för er. Kunden väljer en ledig tid och får en bekräftelse, och ni slipper telefonkö. En AI-chatt kan svara på vanliga frågor medan ni arbetar.",
    "off": "Ett offertformulär som ställer rätt frågor ger er ett bra underlag redan från första förfrågan. Kunden kan bifoga bilder eller mått, och ni slipper ringa tillbaka för att förstå vad jobbet gäller. Bokning av ett första möte kan läggas till.",
    "bes": "Här passar både offertflöde och bokning. Offertformuläret samlar in underlag, bokning av ett första möte ger en tydlig nästa väg och en AI-chatt kan svara på frågor som ofta kommer först.",
    "fraga": "För er är snabba svar viktigast. En tydlig hemsida med telefonnummer, öppettider och en AI-chatt som svarar på vanliga frågor gör att kunden får hjälp direkt, även när ni är upptagna.",
}


def parse_jobs():
    out = []
    for line in JOBS:
        slug, noun, plural, em, intro, searches, needs, trust, mistakes, tool = line.split("|")
        searches = searches.split(";"); needs = needs.split(";"); mistakes = mistakes.split(";")
        faq = [(f"Vad ska en {noun}s hemsida innehålla?", f"Det viktigaste är: {'; '.join(x[0].lower() + x[1:] for x in needs[:4])}. Vi anpassar listan efter just er verksamhet."),
               (f"Hur får {plural} fler kunder via hemsidan?", f"Genom en egen sida för varje tjänst, rubriker som liknar det kunderna söker på, till exempel {searches[0]} och {searches[1]}, och en enkel väg att ta kontakt eller boka."),
               (f"Vad kostar en hemsida för {plural}?", "Starter kostar 5 000 kr i startavgift plus 99–199 kr om året. Pro, med offertflöde, bokning och AI-chatt, kostar 9 000 kr plus 299–399 kr om året. Alla priser anges exklusive moms.")]
        out.append(dict(slug=f"hemsida-for-{slug}", noun=noun, firm=noun, plural=plural, em=em, intro=intro, searches=searches, needs=needs, trust=trust,
                        mistakes=mistakes, tool=TOOLS[tool], faq=faq))
    return out


