LAT0, LON0 = 59.858, 17.639


def dist(lat, lon):
    r = math.pi / 180
    a = math.sin((lat - LAT0) * r / 2) ** 2 + math.cos(LAT0 * r) * math.cos(lat * r) * math.sin((lon - LON0) * r / 2) ** 2
    return 6371 * 2 * math.asin(math.sqrt(a))


