def town_page2(t, others, idx, price_sec, FAQ_SHARED):
    slug, n, lan, lat, lon, kind, near = t.split("|")
    km = dist(float(lat), float(lon))
    mil = round(km / 10)
    d = f"ungefär {mil} mil fågelvägen" if mil >= 10 else f"ungefär {round(km)} km fågelvägen"
    feel = FEEL[kind][idx % 2].format(n=n, l=lan + " län")
    nearby = near.replace(", ", ", ", 1)
    sections = [
        (f"Webbyrå för företag i {n}", [f"¶ {feel}", f"¶ Vi är en liten webbyrå i Uppsala, {d} från {n}, och bygger hemsidor som får kunder att höra av sig. Vi arbetar med företag i {n}, {nearby} och i resten av {lan} län, och i hela Sverige.", "¶ De flesta av våra möten sker på distans, men det går också bra att ses på plats när det passar. Ni pratar med samma person från första samtalet till lansering."]),
        ("Det här får ni", ["¶ En hemsida som ska göra ett jobb för er, inte bara se bra ut:", "Snabb, mobilanpassad design som laddar direkt, även på svag mobiltäckning", "En egen sida för varje tjänst, så att ni syns på sökningar som matchar det ni gör", "Kontaktväg på varje sida: telefon, formulär och, om ni vill, bokning direkt", "Offertflöde som frågar rätt saker, så ni får bra förfrågningar", "AI-chatt som svarar på vanliga frågor medan ni jobbar", "Grundläggande SEO och AI-optimering, så Google och AI-assistenter förstår vad ni gör", "Support och underhåll efter lansering"]),
        (f"Lokal SEO för {n}", [f"¶ När kunder letar efter ett företag nära sig söker de ofta på tjänsten och orten, till exempel hemsida {n} eller webbyrå {n}. För att synas där behöver hemsidan visa tydligt vad ni gör och var ni verkar.", "¶ Vi gör det genom att:", f"Skriva sidtitlar och rubriker som nämner både tjänst och {n} där det är relevant", f"Nämna de orter ni täcker, till exempel {nearby}", "Lägga in strukturerad data som berättar för Google vilket företag ni är", "Hjälpa er att skapa och fylla i en komplett Google-företagsprofil", "Se till att sidan är snabb och fungerar på mobilen, där de flesta lokala sökningar sker", "¶ Vi kan inte lova en viss placering, men grunden blir rätt gjord. Efteråt följer ni resultatet i Testa din sajt och i Google Search Console."]),
        ("Så fungerar samarbetet på distans", ["¶ Det är enklare än många tror. Vi ses på video, ni berättar om företaget, och vi bygger ett första utkast som ni kan klicka runt i direkt. Ändringar tar vi i två omgångar via mejl eller samtal.", "¶ I Starter ingår upp till 10 timmars support och redigering per månad under det första året."]),
        price_sec(f"företag i {n}", idx),
        ("Det första steget", ["¶ Boka ett kort möte, gratis och utan krav. Vi går igenom vad ni vill få ut av hemsidan, tittar på er nuvarande sida om ni har en och säger ärligt vad vi rekommenderar. Ni kan också börja med att testa er sajt i Testa din sajt, ett gratis test som visar hastighet, tillgänglighet och SEO."]),
    ]
    faq = [(f"Jobbar ni med företag i {n}?", f"Ja. Vi sitter i Uppsala men bygger hemsidor åt företag i hela Sverige, bland annat i {lan} län. Möten sker på distans, eller på plats när det passar."),
           (f"Vad kostar en hemsida för ett företag i {n}?", "Starter kostar 5 000 kr i startavgift och Pro 9 000 kr, exklusive moms. Orten påverkar inte priset.")] + FAQ_SHARED
    return dict(slug=f"webbyra-{slug}", title=f"Webbyrå {n} – hemsidor från 5 000 kr", h1=f"Webbyrå för företag i <em>{n}</em>",
                description=f"Webbyrå för företag i {n}: snabba hemsidor med SEO, bokning och offertflöde till fast pris från 5 000 kr. Arbetar på distans eller på plats.",
                lead=f"Vi bygger hemsidor åt företag i {n} och {lan} län: snabba, mobilanpassade och med fast pris från 5 000 kr. Ni pratar med samma person hela vägen.",
                sections=sections, faq=faq, kind="ort", label=f"Webbyrå {n}", short=f"Hemsidor för företag i {n}, {lan} län.", related=others, area=n, lan=lan)
